    BRANCH = #{branch,jdbcType=VARCHAR},            CCY = #{ccy,jdbcType=VARCHAR},            INT_TYPE = #{intType,jdbcType=VARCHAR},            YEAR_BASIS = #{yearBasis,jdbcType=VARCHAR},            EFFECT_DATE = #{effectDate,jdbcType=TIMESTAMP},            INT_BASIS = #{intBasis,jdbcType=VARCHAR},            BASE_RATE = #{baseRate,jdbcType=DECIMAL},            PERIOD_FREQ = #{periodFreq,jdbcType=VARCHAR},            DAY_NUM = #{dayNum,jdbcType=INTEGER},            MATRIX_AMT = #{matrixAmt,jdbcType=DECIMAL},            ACTUAL_RATE = #{actualRate,jdbcType=DECIMAL},            DISC_RATE = #{discRate,jdbcType=DECIMAL},            SPREAD_PERCENT = #{spreadPercent,jdbcType=DECIMAL},            SPREAD_RATE = #{spreadRate,jdbcType=DECIMAL},            MAX_PERCENT = #{maxPercent,jdbcType=DECIMAL},            MIN_PERCENT = #{minPercent,jdbcType=DECIMAL},            MIN_RATE = #{minRate,jdbcType=DECIMAL},            MAX_RATE = #{maxRate,jdbcType=DECIMAL},            COMPANY = #{company,jdbcType=VARCHAR},            TRAN_TIMESTAMP = #{tranTimestamp,jdbcType=VARCHAR},            MIN_SPREAD_RATE = #{minSpreadRate,jdbcType=DECIMAL},            MIN_SPREAD_PERCENT = #{minSpreadPercent,jdbcType=DECIMAL},            MAX_SPREAD_RATE = #{maxSpreadRate,jdbcType=DECIMAL},            MAX_SPREAD_PERCENT = #{maxSpreadPercent,jdbcType=DECIMAL},            PEGGED_INT_TYPE = #{peggedIntType,jdbcType=VARCHAR}        where MATRIX_NO = #{matrixNo,jdbcType=VARCHAR}
